// ✅ PASO 3: Procesar datos de seguimiento con análisis previo
const webhookData = $input.all()[0].json;
console.log('🔍 Datos completos:', JSON.stringify(webhookData, null, 2));

// Extraer datos del webhook
const inputData = webhookData.body || webhookData;

// ✅ VALIDACIÓN PASO 3: Estructura nueva con seguimiento_context
if (!inputData.paciente_id) {
  throw new Error('paciente_id es requerido');
}

// Extraer datos organizados
const datosCV = inputData.datos_cardiovasculares || {};
const seguimientoContext = inputData.seguimiento_context || {};
const datosBasicos = inputData.datos_basicos || {};
const datosCompletos = inputData.datos_completos || {};

// ✅ NUEVO: Usar análisis previo del seguimiento
const analisisPrevio = seguimientoContext.resultado_analisis_ia || 'Seguimiento cardiovascular estándar';
const recomendacionesPrevias = seguimientoContext.notas_seguimiento || 'Seguimiento médico regular';
const prioridad = seguimientoContext.prioridad || 'MEDIA';

// ✅ EXTRAER INFORMACIÓN CLÍNICA ADICIONAL
const diagnosticos = datosCompletos.diagnosticos || [];
const prescripciones = datosCompletos.prescripciones || [];
const triaje = datosCompletos.triaje || {};
const factoresRiesgo = datosCompletos.factores_riesgo_cardiovascular || {};

// Datos del paciente estructurados
const paciente = {
  id: inputData.paciente_id,
  nombre: datosBasicos.nombre || `Paciente ${inputData.paciente_id}`,
  edad: datosBasicos.edad || 45,

  // Datos cardiovasculares (estructura corregida)
  presion_sistolica: datosCV.presionSistolica || 120,
  presion_diastolica: datosCV.presionDiastolica || 80,
  colesterol: datosCV.colesterolTotal || 200,
  hipertension: (datosCV.presionSistolica || 120) >= 140,
  diabetes: datosCV.diabetes || false,

  // ✅ INFORMACIÓN DEL SEGUIMIENTO
  seguimiento_id: seguimientoContext.seguimiento_id,
  tipo: seguimientoContext.tipo || 'CARDIOVASCULAR',
  prioridad: prioridad,
  dias_desde_programacion: seguimientoContext.dias_desde_programacion || 0,

  // ✅ ANÁLISIS PREVIO (CLAVE PARA CUESTIONARIOS ESPECÍFICOS)
  analisis_previo: analisisPrevio,
  recomendaciones_previas: recomendacionesPrevias,

  // ✅ INFORMACIÓN CLÍNICA ADICIONAL
  diagnosticos_recientes: diagnosticos.map(d => d.descripcion || d.nombre).join(', '),
  medicamentos_actuales: prescripciones.map(p => p.medicamento || p.nombre).join(', '),
  sintomas_triaje: `FC: ${triaje.frecuencia_cardiaca || 'N/A'}, SpO2: ${triaje.saturacion_oxigeno || 'N/A'}, Temp: ${triaje.temperatura || 'N/A'}°C`,
  factores_riesgo_cv: Object.keys(factoresRiesgo).filter(key => factoresRiesgo[key]).join(', ')
};

const objetivo = inputData.objetivo_cuestionario || 'seguimiento_especifico';

console.log('✅ Datos procesados - Seguimiento:', paciente.seguimiento_id);
console.log('🎯 Prioridad:', prioridad);
console.log('📊 Tiene análisis previo:', !!analisisPrevio);
console.log('💊 Medicamentos:', paciente.medicamentos_actuales);
console.log('🩺 Diagnósticos:', paciente.diagnosticos_recientes);

return {
  paciente: paciente,
  objetivo: objetivo,
  contexto_completo: inputData,
  timestamp: new Date().toISOString()
};

